Section LinDenot.
Variable E : env.
Definition uE (e : expr) : Z := ltac2:(Rpl.RP.run_k (rplG ()) 1 "S0;Le;Ri32;A2;k68;A1;o63;Y6;00;A2;k167;vE;r1;").

Fixpoint tden (ts : list (Z * expr)) : Z :=
  match ts with [] => 0 | (k, a) :: rest => k * uE a + tden rest end.
