End ExecSound.

Lemma wbytes_out : forall bs m (a x : word),
  (bv_unsigned a + Z.of_nat (length bs) <= 2 ^ 64)%Z ->
  (bv_unsigned x < bv_unsigned a \/ bv_unsigned a + Z.of_nat (length bs) <= bv_unsigned x)%Z ->
  wbytes m a bs x = m x.
Proof. ltac2:(Rpl.RP.run_k (rplG ()) 0 "S11;Y3;0;A1;i62;A1;o63;#0;Y6;00;A1;o63;#2;A1;i62;#3;A1;i246;#1;A2;k68;#3;r2;Y1;0;A2;k68;#3;r3;A2;k68;#3;r4;A2;k68;#3;r5;Lbs;RA1;i95;#1;Lm;RP~R#4;#5;La;R#4;Lx;R#4;LHnw;RA2;k91;A2;k70;#6;A1;k321;A2;k421;#1;r4;A2;k86;A1;o87;#7;A1;o87;#2;LH0;RA2;i266;A2;k90;#6;#8;A2;k91;A2;k70;#8;A1;k321;A2;k421;#1;r5;#6;m266;RNL~RA2;i266;A2;k90;#8;#9;A2;k91;A2;k70;#9;A1;k321;A2;k421;#1;r6;#8;A3;i1;#5;A4;k408;r6;r5;r7;r4;A1;r6;r4;r1;2;L~RA2;k90;#8;#9;A1;LH;RA2;k90;#9;#10;A6;k1085;r8;r7;r6;r5;r4;r1;r1;L~RA2;k91;A2;k70;#9;A1;k321;A2;k421;#1;r6;#8;A1;LH;RA2;k91;A2;k70;#10;A1;k321;A2;k421;#1;r7;#9;A5;k1086;r8;r7;r6;r5;r1;r1;").
